// Entrada de ejemplo para ejecución manual (misma forma que el body del webhook).
return [{
  json: {
    body: {
      nombres: [
        'Mercado Libre',
        'Banco de la República Oriental del Uruguay',
        'Empresa Inexistente XYZ 123'
      ]
    }
  }
}];

// CONFIG CENTRAL DEL FLUJO
// - Recibe la entrada (webhook: body.nombres | manual: nombres).
// - Define umbrales, rutas y la REGLA EXPLÍCITA DE PONDERACIÓN del score.
// - NO contiene claves de API: todas viven en n8n Credentials (cifradas con N8N_ENCRYPTION_KEY).
const entrada = $input.first().json;
let rawNombres = (entrada.body && entrada.body.nombres) || entrada.nombres || entrada['Nombres de Empresas o Personas'] || entrada['nombres_input'] || [];

if (typeof rawNombres === 'string') {
  rawNombres = rawNombres.split(/[\r\n,;]+/).map(s => s.trim()).filter(Boolean);
} else if (!Array.isArray(rawNombres)) {
  rawNombres = [];
}
const nombres = rawNombres;

return [{
  json: {
    nombres,
    user_agent: 'SOC-TI-Dominios/1.0 (n8n; contacto: soc@example.com)',
    max_ips_por_dominio: 3,
    umbral_confianza_dominio: 0.35,
    tlds_heuristica: [
      'gov.py', 'gob.py', 'com.py', 'edu.py', 'org.py', 'py',
      'gov', 'gob', 'com', 'com.ar', 'com.uy', 'com.br', 'cl', 'co', 'net', 'org', 'io', 'tech'
    ],
    dominios_excluidos: [
      'wikipedia.org', 'wikidata.org', 'linkedin.com', 'facebook.com', 'instagram.com', 'x.com', 'twitter.com',
      'youtube.com', 'tiktok.com', 'crunchbase.com', 'bloomberg.com', 'glassdoor.com', 'indeed.com',
      'google.com', 'apple.com', 'amazon.com', 'github.com', 'medium.com', 'reddit.com', 'dnb.com',
      'zoominfo.com', 'opencorporates.com', 'mercadolibre.com.ar', 'mercadolibre.com.uy', 'blogspot.com', 'wordpress.com'
    ],
    rutas_iso: ['/', '/certificaciones', '/calidad', '/iso', '/certifications'],

    // Peso de cada técnica de coincidencia nombre -> dominio (se suman; tope 1.0)
    pesos_descubrimiento: {
      wikidata: 0.5,        // P856 "sitio web oficial" de la entidad encontrada
      crtsh: 0.3,           // certificados OV/EV con O=<nombre> en Certificate Transparency
      busqueda_top1: 0.35,  // 1er resultado orgánico del buscador
      busqueda_top5: 0.2,   // resultados 2..5
      heuristica: 0.35,     // slug(nombre) + TLD configurado (permite descubrir si resuelve por DNS)
      bonus_token: 0.15     // un token significativo del nombre aparece en el label del dominio
    },

    // ================= REGLA DE PONDERACIÓN DEL SCORE (1-100) =================
    // score = clamp( base + Σ puntos , 1 , 100 )
    // - Cada fuente tiene un TOPE de puntos positivos (max). Los negativos (señales buenas) no tienen tope.
    // - Fuentes por IP (Shodan, AbuseIPDB, IP-API, Feodo): se toma la PEOR IP del dominio.
    // - IP de infraestructura compartida (CDN/cloud o IP-API Hosting): AbuseIPDB e IP-API x cdn_factor.
    // - Fuente no disponible => 0 puntos + marca "no_disponible" (nunca se imputa un valor).
    pesos: {
      base: 10,
      min: 1,
      max: 100,
      cdn_factor: 0.5,
      abuseipdb: { max: 30, alto: { umbral: 75, pts: 30 }, medio: { umbral: 25, pts: 18 }, bajo: { umbral: 1, pts: 8 }, limpio: -3 },
      abusech:   { max: 30, feodo_c2: 30, urlhaus_online: 20, urlhaus_historico: 8, threatfox_ioc: 15, limpio: -3 },
      ipapi:     { max: 15, proxy: 15, hosting: 5, limpio: -2 },
      shodan:    { max: 20, cves_1: 8, cves_5: 12, puerto_riesgo: 3, max_puertos: 8, solo_web: -2 },
      mxtoolbox: { max: 15, blacklist: 8, sin_spf: 2, spf_permisivo: 3, sin_dmarc: 3, dmarc_none: 1, correo_ok: -3 },
      iso:       { iso27001_declarado: -1 }
    },
    puertos_riesgo: [21, 23, 25, 110, 135, 139, 143, 445, 1433, 1521, 2375, 3306, 3389, 5432, 5900, 5985, 6379, 9200, 11211, 27017],
    puertos_web: [80, 443, 8080, 8443],
    regex_infra_compartida: 'cloudflare|akamai|fastly|cloudfront|incapsula|imperva|sucuri|amazon|google|microsoft|azure'
  }
}];

// ---- helpers comunes (inyectados por build.py) ----
// Interpreta la salida de un nodo HTTP configurado con onError=continueRegularOutput.
// Si la petición falló, n8n devuelve { error: <string|objeto> } en lugar de la respuesta.
function estadoHttp(j) {
  if (!j || j.error === undefined) return { ok: true, code: null, msg: '' };
  const e = j.error;
  const txt = typeof e === 'string' ? e : JSON.stringify(e);
  let code = (e && typeof e === 'object') ? (e.httpCode || e.status || e.statusCode || (e.cause && e.cause.status) || null) : null;
  if (!code) { const m = txt.match(/\b([45]\d\d)\b/); if (m) code = m[1]; }
  return { ok: false, code: code ? String(code) : null, msg: txt.slice(0, 300) };
}
function motivoFallo(st) {
  if (st.code === '429') return 'límite de tasa (429) tras reintentos';
  if (st.code === '401' || st.code === '403') return `credencial inválida o sin permiso (${st.code})`;
  return `${st.code ? st.code + ' ' : ''}${st.msg}`.trim() || 'sin respuesta';
}
// Dominio registrable aproximado (sin Public Suffix List completa).
function registrable(h) {
  h = String(h || '').trim().toLowerCase()
    .replace(/^[a-z]+:\/\//, '').split(/[\/?#:]/)[0]
    .replace(/^\*\./, '').replace(/^www\./, '').replace(/\.$/, '');
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(h)) return null;
  const p = h.split('.');
  if (p.length <= 2) return h;
  const sld = p[p.length - 2], tld = p[p.length - 1];
  const tres = tld.length === 2 && ['com', 'net', 'org', 'gov', 'gob', 'edu', 'co', 'ac', 'mil', 'nom', 'int'].includes(sld);
  return p.slice(tres ? -3 : -2).join('.');
}
// ---- fin helpers ----

// Normaliza y deduplica nombres; prepara tokens, slug, detección de dominio directo y consulta SPARQL de Wikidata.
const cfg = $('Config').first().json;
const STOP = new Set(['srl', 'ltda', 'inc', 'llc', 'corp', 'group', 'grupo', 'del', 'las', 'los', 'and', 'the', 'cia',
  'company', 'sociedad', 'anonima', 'limitada', 'holding', 'internacional']);
const vistos = new Set();
const out = [];
for (const raw of cfg.nombres) {
  const nombre = String(raw || '').trim().replace(/\s+/g, ' ');
  if (!nombre) continue;
  const clave = nombre.toLowerCase();
  if (vistos.has(clave)) continue;           // evita procesar dos veces el mismo nombre
  vistos.add(clave);

  // Detectar si el usuario ingresó directamente un dominio o URL (ej: technoma.com.py)
  let dominioDirecto = null;
  const mDom = nombre.toLowerCase().match(/(?:https?:\/\/)?([a-z0-9.-]+\.[a-z]{2,})/i);
  if (mDom) {
    dominioDirecto = registrable(mDom[1]);
  }

  const base = nombre.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const tokens = base.split(/[^a-z0-9]+/).filter(t => t.length >= 2 && !STOP.has(t));
  const slug = tokens.join('');
  const acronimo = tokens.length >= 2 && tokens.length <= 5 ? tokens.map(t => t[0]).join('') : null;
  const slugPrimeroUltimo = tokens.length >= 2 ? (tokens[0] + tokens[tokens.length - 1]) : null;
  const esc = nombre.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const sparql = `SELECT ?item ?itemLabel ?website WHERE { SERVICE wikibase:mwapi { bd:serviceParam wikibase:endpoint "www.wikidata.org"; wikibase:api "EntitySearch"; mwapi:search "${esc}"; mwapi:language "es". ?item wikibase:apiOutputItem mwapi:item. } ?item wdt:P856 ?website. SERVICE wikibase:label { bd:serviceParam wikibase:language "es,en". } } LIMIT 5`;
  out.push({ json: { nombre, tokens, slug, acronimo, slug_primero_ultimo: slugPrimeroUltimo, sparql, dominio_directo: dominioDirecto } });
}
return out;

// ---- helpers comunes (inyectados por build.py) ----
// Interpreta la salida de un nodo HTTP configurado con onError=continueRegularOutput.
// Si la petición falló, n8n devuelve { error: <string|objeto> } en lugar de la respuesta.
function estadoHttp(j) {
