  return `${st.code ? st.code + ' ' : ''}${st.msg}`.trim() || 'sin respuesta';
}
// Dominio registrable aproximado (sin Public Suffix List completa).
function registrable(h) {
  h = String(h || '').trim().toLowerCase()
    .replace(/^[a-z]+:\/\//, '').split(/[\/?#:]/)[0]
    .replace(/^\*\./, '').replace(/^www\./, '').replace(/\.$/, '');
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(h)) return null;
  const p = h.split('.');
  if (p.length <= 2) return h;
  const sld = p[p.length - 2], tld = p[p.length - 1];
  const tres = tld.length === 2 && ['com', 'net', 'org', 'gov', 'gob', 'edu', 'co', 'ac', 'mil', 'nom', 'int'].includes(sld);
  return p.slice(tres ? -3 : -2).join('.');
}
// ---- fin helpers ----

// Modo: una vez por ítem. crt.sh devuelve un array JSON (se pidió como texto para que n8n no lo divida).
// Agrega también los candidatos heurísticos (slugs + acrónimos + TLDs) y dominios directos.
const cfg = $('Config').first().json;
const ctx = $('Norm Wikidata').item.json;
const st = estadoHttp($json);
let crtsh;
if (!st.ok) {
  crtsh = { estado: 'no_disponible', motivo: motivoFallo(st), dominios: [] };
} else {
  let arr;
  try { arr = JSON.parse($json.data || '[]'); } catch (e) { arr = null; }
  if (!Array.isArray(arr)) {
    crtsh = { estado: 'no_disponible', motivo: 'respuesta no JSON (crt.sh saturado)', dominios: [] };
  } else {
    const cuenta = {};
    for (const c of arr) {
      for (const n of String(c.name_value || '').split('\n')) {
        const d = registrable(n);
        if (d) cuenta[d] = (cuenta[d] || 0) + 1;
      }
    }
    const dominios = Object.entries(cuenta).sort((a, b) => b[1] - a[1]).slice(0, 10).map(x => x[0]);
    crtsh = { estado: 'ok', certificados: arr.length, dominios };
  }
}

// Generación heurística (slugs + acrónimos) y dominios directos
// Si el usuario ya ingresó explícitamente un dominio/URL (ej: pechugon.com.py), evitar 50+ permutaciones heurísticas
const esDominioExplicito = Boolean(ctx.dominio_directo) && !/\s/.test(ctx.nombre || '');
const heuristicaDominios = [];
if (!esDominioExplicito) {
  const slugs = [];
  if (ctx.slug && ctx.slug.length >= 3) slugs.push(ctx.slug);
  if (ctx.acronimo && ctx.acronimo.length >= 2 && ctx.acronimo !== ctx.slug) slugs.push(ctx.acronimo);
  if (ctx.slug_primero_ultimo && ctx.slug_primero_ultimo.length >= 3 && !slugs.includes(ctx.slug_primero_ultimo)) {
    slugs.push(ctx.slug_primero_ultimo);
  }
  for (const s of slugs) {
    for (const t of cfg.tlds_heuristica) {
      heuristicaDominios.push(`${s}.${t}`);
    }
  }
}

const heuristica = {
  estado: 'ok',
  dominios: heuristicaDominios
};
const directo = {
  estado: 'ok',
  dominios: ctx.dominio_directo ? [ctx.dominio_directo] : []
};

return { json: { ...ctx, descubrimiento: { ...ctx.descubrimiento, crtsh, heuristica, directo } } };

// Modo: una vez para todos. Lista ÚNICA de dominios candidatos (de todos los nombres) para resolver DNS.
// Emite tanto el dominio raíz como www.<dominio> para no descartar portales que solo configuran www.
const set = new Set();
for (const it of $input.all()) {
  const d = it.json.descubrimiento;
  (d.directo && d.directo.dominios || []).forEach(x => set.add(x));
  (d.wikidata.dominios || []).forEach(x => set.add(x));
  (d.crtsh.dominios || []).forEach(x => set.add(x));
  (d.heuristica.dominios || []).forEach(x => set.add(x));
}
const out = [];
for (const dom of set) {
  out.push({ json: { dominio: dom, host_dns: dom, es_www: false }, pairedItem: { item: 0 } });
  out.push({ json: { dominio: dom, host_dns: `www.${dom}`, es_www: true }, pairedItem: { item: 0 } });
}
return out.length ? out : [{ json: { sin_candidatos: true }, pairedItem: { item: 0 } }];

// ---- helpers comunes (inyectados por build.py) ----
// Interpreta la salida de un nodo HTTP configurado con onError=continueRegularOutput.
// Si la petición falló, n8n devuelve { error: <string|objeto> } en lugar de la respuesta.
function estadoHttp(j) {
  if (!j || j.error === undefined) return { ok: true, code: null, msg: '' };
  const e = j.error;
  const txt = typeof e === 'string' ? e : JSON.stringify(e);
  let code = (e && typeof e === 'object') ? (e.httpCode || e.status || e.statusCode || (e.cause && e.cause.status) || null) : null;
  if (!code) { const m = txt.match(/\b([45]\d\d)\b/); if (m) code = m[1]; }
  return { ok: false, code: code ? String(code) : null, msg: txt.slice(0, 300) };
}
function motivoFallo(st) {
  if (st.code === '429') return 'límite de tasa (429) tras reintentos';
  if (st.code === '401' || st.code === '403') return `credencial inválida o sin permiso (${st.code})`;
  return `${st.code ? st.code + ' ' : ''}${st.msg}`.trim() || 'sin respuesta';
}
// Dominio registrable aproximado (sin Public Suffix List completa).
function registrable(h) {
  h = String(h || '').trim().toLowerCase()
    .replace(/^[a-z]+:\/\//, '').split(/[\/?#:]/)[0]
    .replace(/^\*\./, '').replace(/^www\./, '').replace(/\.$/, '');
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(h)) return null;
  const p = h.split('.');
  if (p.length <= 2) return h;
  const sld = p[p.length - 2], tld = p[p.length - 1];
  const tres = tld.length === 2 && ['com', 'net', 'org', 'gov', 'gob', 'edu', 'co', 'ac', 'mil', 'nom', 'int'].includes(sld);
  return p.slice(tres ? -3 : -2).join('.');
}
// ---- fin helpers ----

// Modo: una vez para todos. Cruza candidatos + DNS, calcula confianza de coincidencia por nombre,
// separa aceptados / posibles / descartados y REGISTRA los nombres sin dominio (el flujo continúa).
const cfg = $('Config').first().json;
const W = cfg.pesos_descubrimiento;
const esPrivada = ip => /^(10\.|127\.|0\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.)/.test(ip);

// 1) Resultado DNS por dominio (agrega respuestas del dominio raíz y de www.)
const dns = {};
let resol = [];
try { resol = $('DoH Candidatos').all(); } catch (e) { resol = []; }
const cands = $('Expandir candidatos').all();
resol.forEach((r, i) => {
  const itemCand = cands[i] && cands[i].json;
  if (!itemCand || !itemCand.dominio) return;
  const dom = itemCand.dominio;
  dns[dom] = dns[dom] || { estado: 'no_disponible', ips: [], usa_www: false };
  const st = estadoHttp(r.json);
  if (!st.ok) return;
  const ips = [...new Set((r.json.Answer || []).filter(a => a.type === 1).map(a => a.data))];
  const publicas = ips.filter(ip => !esPrivada(ip));
  if (publicas.length > 0) {
    dns[dom].estado = 'ok';
    publicas.forEach(ip => {
      if (!dns[dom].ips.includes(ip)) dns[dom].ips.push(ip);
    });
    if (itemCand.es_www && dns[dom].ips.length === publicas.length) {
      dns[dom].usa_www = true;
    }
  } else if (dns[dom].estado !== 'ok') {
    dns[dom].estado = r.json.Status === 0 ? (ips.length ? 'solo_ip_privada' : 'sin_registro_a') : 'nxdomain';
  }
});

// 2) Evaluación por nombre
const nombres = $('Norm crt.sh').all().map(i => i.json);
const resumenNombres = [], sinDominio = [], globales = new Map();
for (const n of nombres) {
  const d = n.descubrimiento;
  const cand = new Map();
  const sumar = (dom, fuente, pts) => {
    if (!dom) return;
    const c = cand.get(dom) || { dominio: dom, fuentes: [], confianza: 0 };
    if (!c.fuentes.includes(fuente)) { c.fuentes.push(fuente); c.confianza += pts; }
    cand.set(dom, c);
  };
  (d.directo && d.directo.dominios || []).forEach(x => sumar(x, 'directo', 1.0));
  (d.wikidata.dominios || []).forEach(x => sumar(x, 'wikidata', W.wikidata));
  (d.crtsh.dominios || []).forEach(x => sumar(x, 'crt.sh', W.crtsh));
  if (d.busqueda && d.busqueda.dominios) {
    d.busqueda.dominios.forEach(x => sumar(x.dominio, `busqueda#${x.posicion}`, x.posicion === 1 ? W.busqueda_top1 : W.busqueda_top5));
  }
  (d.heuristica.dominios || []).forEach(x => sumar(x, 'heuristica', W.heuristica));

  const aceptados = [], posibles = [], descartados = [];
  for (const c of cand.values()) {
    const label = c.dominio.split('.')[0];
    const matchToken = (n.acronimo && label === n.acronimo) || (n.slug_primero_ultimo && label === n.slug_primero_ultimo) || n.tokens.some(t => (t.length >= 3 && label.includes(t)) || (label.length >= 3 && t.includes(label)));
    if (matchToken) { c.confianza += W.bonus_token; c.fuentes.push('token_en_dominio'); }
    c.confianza = Math.min(1, Math.round(c.confianza * 100) / 100);
    const r = dns[c.dominio] || { estado: 'no_resuelto', ips: [], usa_www: false };
    c.dns = r.estado;
    c.ips = r.ips.slice(0, cfg.max_ips_por_dominio);
    c.url = r.usa_www ? `https://www.${c.dominio}` : `https://${c.dominio}`;
    const soloHeur = c.fuentes.every(f => f === 'heuristica' || f === 'token_en_dominio');
    if (!r.ips.length) {
      if (!soloHeur) descartados.push({ ...c, motivo: r.estado === 'no_disponible' ? 'DNS no disponible' : `no resuelve a IP pública (${r.estado})` });
    } else if (c.confianza >= cfg.umbral_confianza_dominio) {
      aceptados.push(c);
    } else {
      posibles.push({ ...c, motivo: 'confianza de coincidencia insuficiente (revisión manual)' });
    }
  }
  aceptados.sort((a, b) => b.confianza - a.confianza);

  const estadoFuentes = { wikidata: d.wikidata.estado, crtsh: d.crtsh.estado };
  const motivosFuentes = {};
  for (const k of ['wikidata', 'crtsh']) if (d[k] && d[k].motivo) motivosFuentes[k] = d[k].motivo;

  const reg = { nombre: n.nombre, estado: aceptados.length ? 'con_dominio' : 'sin_dominio', dominios_aceptados: aceptados, posibles, descartados, estado_fuentes: estadoFuentes, motivos_fuentes: motivosFuentes };
  resumenNombres.push(reg);

  if (!aceptados.length) {
